local PVPArenaMain = Class("PVPArenaMain")

------------ import ------------
local util          = require 'XLua.util'
local CoWait        = CS.Engine.Lib.CoWait
local cs_coroutine  = require('XLua.cs_coroutine')
local KTool         = CS.Engine.Lib.KTool
local Animator      = CS.UnityEngine.Animator
---@type PVPArenaUtils
local PVPArenaUtils = import('Game.Utils.PVPArenaUtils')

local UIModule      = CS.Engine.UI.UIModule
local Yielders      = CS.Engine.Lib.Yielders
---@type PVPArenaComponent
local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
------------ import ------------

------------ define ------------

local PVPArenaTimeLineNodePath  = "Game.UI.PVPArena.PVPArenaTimeLineNode"
local PVPArenaMainPanelNodePath = "Game.UI.PVPArena.PVPArenaMainPanelNode"
local PVPArenaPointNodePath     = "Game.UI.PVPArena.PVPArenaPointNode"

local StringToHash = Animator.StringToHash
local AnimateName = {
    Period1 = StringToHash("Period1"), --- 小组赛阶段（在右边）
    Period2 = StringToHash("Period2"), --- 最终赛阶段（在左边）
    Period3 = StringToHash("Period3"), --- 巅峰未开启（在左边）
}
------------ define ------------

function PVPArenaMain:__init()
    self.isInit = true
end

function PVPArenaMain:__delete()
end

function PVPArenaMain:Awake()
    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)

    self.__EventRequestHomeSuccess          = Events.AddListener(Constants.EventNames.PVPArenaRequestHomeSuccess, Bind(self, self.OnEventRequestHomeSuccess))
    
    KTool.SetActive(self.PanelNode.gameObject, false)
end

function PVPArenaMain:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            GameUtils.SetUICameraProjection(false)

            self.isInitialize = true
            pvpArenaComponent:SetIsEntryPVP(true)
            ---1. 加载 建筑预制件
            pvpArenaComponent:InitMansionsRoot()
            ---2. 请求数据
            local co = pvpArenaComponent:RequestHome()
            if not isNull(co) then
                cs_coroutine.yield_return(co)
            end

        end, function()
            printError("%s", debug.traceback())
        end)

    end))
    return coWait
end

function PVPArenaMain:OnFocus(focus)
    KTool.SetActive(self.controller.gameObject, checkBool(focus))
    if focus then
        CfUtils.SetTopCommonCb(Bind(self, self.OnCustomBackHandlerAction))
    else
        CfUtils.ResetNavigatorCustomBackAction()
    end
end

function PVPArenaMain:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.isInitialize = false
        self:OnEventRequestHomeSuccess()

    end))
    return coWait
end

function PVPArenaMain:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        GameUtils.SetUICameraProjection(true)
        
        self:ReleaseCache()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function PVPArenaMain:InitAnimateNameAndVenuePos()

    local seasonFlag      = pvpArenaComponent:GetSeasonFlag()
    local animateName, venuePos
    if seasonFlag == Constants.PVPArenaSeasonFullStatus.Closed then
        animateName = AnimateName.Period3
        venuePos = pvpArenaComponent:GetGroupVenuePos()
    elseif seasonFlag == Constants.PVPArenaSeasonFullStatus.Final or seasonFlag == Constants.PVPArenaSeasonFullStatus.OffSeason then
        animateName = AnimateName.Period2
        venuePos = pvpArenaComponent:GetGroupVenuePos()
    else
        venuePos = pvpArenaComponent:GetFinalVenuePos()
        animateName = AnimateName.Period1
    end
    return animateName, venuePos
end

