---OnEventRequestHomeSuccess
---home 接口请求成功
function PVPArenaMain:OnEventRequestHomeSuccess(isBroadcast)
    if isBroadcast and self.isInitialize == true then
        return
    end
    self:ReleaseCo()
    ---@type PVPArenaDojo
    local pvpArenaDojo      = pvpArenaComponent:GetPVPArenaDojo()
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    local isAudience        = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience
    self.co = cs_coroutine.start(function ()
        xTry(function()
            local wait = Yielders.GetWaitForSeconds(0.3)
            -- while not self.isMansionLoadComplete do
            --     cs_coroutine.yield_return(wait)
            -- end

            -- cs_coroutine.yield_return(wait)
            local isPop, isPopReady = pvpArenaComponent:CheckDialog()
            if isPop and not isPopReady then
                return
            end

            if isAudience and checkNumber(pvpArenaEntryDojo.seasonStatus) == Constants.PVPArenaSeasonStatus.Quiz and checkNumber(pvpArenaDojo.isFirst) >= 1 then
                --- 弹出后设置 第一次进入为 0
                pvpArenaDojo.isFirst = 0

                local id = Constants.UITypeIds.UICommonRewardPop
                local quizGoodsId = pvpArenaComponent:GetParamsRowNum(Constants.PVPArenaParamsIds.QuizGoodsId)
                local rewards = {{goodsId = quizGoodsId, num = pvpArenaDojo.quizTicketNum}}
                UIModule.OpenDialog({ id = id, parameters = {rewards = rewards} })
                local CheckIsShowDialogByIdMap = GameUtils.CheckIsShowDialogByIdMap
                while CheckIsShowDialogByIdMap({ [id] = true }) do
                    cs_coroutine.yield_return(wait)
                end
            end
            self:UpdateHealthNodes(pvpArenaDojo)

            self:RefreshUI(pvpArenaDojo)
        end, function()
            printError("%s", debug.traceback())
        end)
    end)
end

function PVPArenaMain:ReleaseCo()
    if self.co then
        cs_coroutine.stop(self.co)
        self.co = nil
    end

end

function PVPArenaMain:OnEventPVPArenaMainUpdateShowState(isShow)
    KTool.SetActive(self.controller.gameObject, isShow)
end

function PVPArenaMain:UpdateHealthNodes(pvpArenaDojo)
    if not self.isInit then return end
    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    local t = {}
    local isAudience        = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience
    local quizGoodsId
    local quizRewardGoodsId = pvpArenaComponent:GetParamsRowNum(Constants.PVPArenaParamsIds.QuizRewardGoodsId)
    table.insert(t, quizRewardGoodsId)
    if isAudience then
        quizGoodsId       = pvpArenaComponent:GetParamsRowNum(Constants.PVPArenaParamsIds.QuizGoodsId)
        table.insert(t, quizGoodsId)
    end
    GameUtils.UpdateNavBarShowGoods(t)
end

function PVPArenaMain:RefreshUI(pvpArenaDojo)
    self:RefreshTineLineNode()
    self:RefreshPanelNode()
    self:RefreshPVPPointNode()

    if self.isInit then
        self:RefreshTextNumber(pvpArenaDojo)
        KTool.SetActive(self.PanelNode.gameObject, true)
        --- 显示 特效
        KTool.SetActive(self.UI_PVPMainRoot.gameObject, true)
        self.isInit = nil
    end

    local animateName, venuePos = self:InitAnimateNameAndVenuePos()
    if self.animateName ~= animateName  then
        if self.venuePos ~= venuePos then
            self.PVPPointNode.anchoredPosition = PVPArenaUtils.VenueWorldPosition2VenueUIPosition(venuePos, self.Root.transform)
            self.venuePos = venuePos
        end

        self.animateName = animateName
        --- 显示 动画
        self:PlayAnimateByType(animateName)
    end
end

function PVPArenaMain:RefreshTineLineNode()
    xTry(function()
        ---@type PVPArenaTimeLineNode
        local mbEnv = CfUtils.GetLuaScr(self.PVPTimeLineNode.gameObject, PVPArenaTimeLineNodePath)
        if mbEnv == nil then return end

        mbEnv:RefreshUI(true)

    end)
end

function PVPArenaMain:RefreshPanelNode()
    ---@type PVPArenaMainPanelNode
    local mbEnv = CfUtils.GetLuaScr(self.PanelNode.gameObject, PVPArenaMainPanelNodePath)
    if mbEnv == nil then return end

    mbEnv:RefreshUI()
end

function PVPArenaMain:RefreshPVPPointNode()
    ---@type PVPArenaPointNode
    local mbEnv = CfUtils.GetLuaScr(self.PVPPointNode.gameObject, PVPArenaPointNodePath)
    if mbEnv == nil then return end

    mbEnv:RefreshUI()
end

---RefreshTextNumber
---@param pvpArenaDojo PVPArenaDojo
function PVPArenaMain:RefreshTextNumber(pvpArenaDojo)
    self.TxtNumber.text = pvpArenaDojo.seasonId
end

---PlayAnimateByType
function PVPArenaMain:PlayAnimateByType(animateName)
    self.Root:Rebind()
    self.Root:Play(animateName)
end

